	private static MapData.Step st(String mech, int a, int b, String room, int x, int z) {
		MapData.Step s = new MapData.Step();
		s.mech = mech;
		s.a = a;
		s.b = b;
		s.room = room;
		s.pos = MapBuilder.p(x, 0, z);
		return s;
	}

	private static void task(MapData m, String name, int diff, MapData.Step... steps) {
		MapData.TaskDef t = new MapData.TaskDef();
		t.name = name;
		t.diff = diff;
		for (MapData.Step s : steps) t.steps.add(s);
		m.tasks.add(t);
	}

	private static void vent(MapData m, int x, int z, int group) {
		MapData.Vent v = new MapData.Vent();
		v.pos = MapBuilder.p(x, 0, z);
		v.group = group;
		m.vents.add(v);
		MapBuilder.set(x, 0, z, "minecraft:iron_trapdoor");
	}

	private static void switchAt(MapData m, int x, int z) {
		m.switches.add(MapBuilder.p(x, 0, z));
		MapBuilder.set(x, 0, z, "minecraft:lever[face=floor,facing=north,powered=true]");
	}
